package org.jlinalg.cli;
import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;

/** Complete saved namespace and scientific consistency; no original-host access or model refit. */
final class DiannBundle {
    private DiannBundle() { }
    private static final Set<String> CONTROL=Set.of("manifest.json","COMPLETED.json","INCOMPLETE.json");
    static Pin producer()throws IOException {
        try{Path jar=Path.of(DiannBundle.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();if(!Files.isRegularFile(jar,LinkOption.NOFOLLOW_LINKS))throw new DiannRuntime.Unavailable("Execute capture/readback using the exact packaged producing JAR; class-directory execution is not admitted");return pin(jar,1000000000L,()->{});}catch(java.net.URISyntaxException error){throw new IOException(error);}
    }
    static Map<String,Object> snapshot(Path root,DiannRequest.Spec s,Runnable check)throws IOException {
        var result=new TreeMap<String,Object>();long[] total={0};int[] nodes={0};
        Files.walkFileTree(root,new SimpleFileVisitor<Path>(){
            private void visit(Path path,boolean directory)throws IOException {
                check.run();if(path.equals(root))return;String name=root.relativize(path).toString().replace('\\','/');if(CONTROL.contains(name))return;
                require(++nodes[0]<=s.process().fileCount()&&!Files.isSymbolicLink(path)&&path.toRealPath().equals(path),"Capture namespace capacity/type/canonical-path failure");
                if(directory)result.put(name,Map.of("kind","directory"));else {require(Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS),"Special capture node is not admitted");Pin value=pin(path,s.process().fileBytes(),check);total[0]=Math.addExact(total[0],value.bytes());require(total[0]<=s.process().workspaceBytes(),"Complete captured byte population exceeds workspace capacity");result.put(name,Map.of("kind","file","pin",value));}
            }
            @Override public FileVisitResult preVisitDirectory(Path path,BasicFileAttributes attributes)throws IOException{visit(path,true);return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path path,BasicFileAttributes attributes)throws IOException{visit(path,false);return FileVisitResult.CONTINUE;}
        });
        var top=new HashSet<String>();for(String name:result.keySet())top.add(name.split("/",2)[0]);require(top.equals(Set.of("inputs","engine","outputs","processes","runtime","request.json","source-inputs.json","execution.json","ATTRIBUTION.txt","WARNINGS.md","OUTPUT-AUDIT.json")),"Unexpected/missing top-level capture member");
        long input=integer(object(json(root.resolve("source-inputs.json"),(int)Math.min(1000000000L,s.capacity().outputBytes()))).get("complete_original_bytes"),1,s.capacity().inputBytes());require(total[0]-input<=s.capacity().outputBytes()+33554432,"Complete generated bytes exceed output capacity plus32MiB metadata reserve");return result;
    }
    static Map<String,Object> audit(Path root,DiannRequest.Spec s,Path scratch,Runnable check)throws IOException {
        DiannInputs.verify(root,s,false,check);var execution=object(json(root.resolve("execution.json"),1048576));
        keys(execution,"schema_version","engine","edition","execution_root","home","prediction_command","quantification_command","environment","original_binaries_modified");integer(execution.get("schema_version"),1,1);
        String oldRoot=text(execution.get("execution_root")),home=text(execution.get("home"));require(oldRoot.startsWith("/")&&home.startsWith("/")&&"original".equals(execution.get("engine"))&&s.edition().equals(execution.get("edition"))&&Boolean.FALSE.equals(execution.get("original_binaries_modified")),"Different/expanded original execution claim");
        var prediction=DiannWorkflow.predictionCommand(oldRoot,home,s);var quantification=DiannWorkflow.quantificationCommand(oldRoot,home,s);
        require(prediction.equals(strings(execution.get("prediction_command")))&&quantification.equals(strings(execution.get("quantification_command"))),"Captured original scientific options differ from explicit request");
        var provenance=object(json(root.resolve("runtime/provenance.json"),1048576));keys(provenance,"edition","original_program","original_files","linux_helpers","original_binaries_modified");var profile=DiannRuntime.profile(s.edition());
        require(s.edition().equals(provenance.get("edition"))&&profile.get("program").equals(provenance.get("original_program"))&&NextflowJson.json(profile.get("files")).equals(NextflowJson.json(provenance.get("original_files")))&&Boolean.FALSE.equals(provenance.get("original_binaries_modified")),"Captured original runtime identity differs");
        var helpers=object(provenance.get("linux_helpers"));require(helpers.keySet().equals(Set.of("/usr/bin/setsid","/usr/bin/prlimit")),"Captured Linux helper population differs");for(Object value:helpers.values())fingerprint(value,16777216);
        var expectedEnvironment=Map.of("PATH","/usr/bin:/bin","LANG","C","LC_ALL","C","LD_LIBRARY_PATH",home,"OMP_NUM_THREADS",Integer.toString(s.quantification().threads()),"OPENBLAS_NUM_THREADS","1","MKL_NUM_THREADS",Integer.toString(s.quantification().threads()));
        require(NextflowJson.json(expectedEnvironment).equals(NextflowJson.json(execution.get("environment"))),"Captured original execution environment differs");
        process(root,"prediction",prediction,oldRoot,s);process(root,"quantification",quantification,oldRoot,s);
        var warnings=new ArrayList<String>();warnings.addAll(DiannWorkflow.diagnostics(root,s,"prediction"));warnings.addAll(DiannWorkflow.diagnostics(root,s,"quantification"));
        var generation=DiannWorkflow.predictionAudit(root,s,check);var runs=new ArrayList<DiannOutputAudit.Run>();for(int i=0;i<s.runs().size();i++)runs.add(new DiannOutputAudit.Run(oldRoot+"/"+DiannInputs.runRoot(i,s.runs().get(i)),s.runs().get(i).name()));
        var c=s.capacity();var limits=new DiannOutputAudit.Capacity(new DiannReportRows.Limits(c.reportRows(),c.outputBytes(),256,1048576,4096,c.parquetMemory()),new DiannReference.Limits(c.referenceRecords(),c.referenceResidues(),c.inputBytes(),1048576),c.joins());
        var outputs=DiannOutputAudit.audit(root.resolve("outputs"),root.resolve("inputs/reference.fasta"),s.edition(),runs,oldRoot+"/outputs",s.quantification().q(),s.quantification().mbr(),limits,scratch,check);
        return Map.of("schema_version",1,"status","COMPLETE_ORIGINAL_DIA_NN_INPUT_OUTPUT_CAPTURE_CONSISTENCY","edition",s.edition(),"generation",generation,"original_warnings",warnings,"original_outputs",outputs,"original_model_refitted_by_Java",false,"neural_training_convergence_certified",false,"whole_paper_reproduced",false);
    }
    static void verify(Path supplied,boolean precommit,Path scratch,Runnable check)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();directory(root);require(scratch!=null&&!scratch.toAbsolutePath().normalize().startsWith(root)&&!root.startsWith(scratch.toAbsolutePath().normalize()),"Saved audit scratch must be separate from complete capture");
        require(!Files.exists(root.resolve("FAILURE.json"))&&Files.exists(root.resolve("INCOMPLETE.json"))==precommit,"Failed/incomplete DIA-NN result is not admitted");
        var done=object(json(root.resolve("COMPLETED.json"),1048576));keys(done,"schema_version","status","manifest","analysis_admitted");integer(done.get("schema_version"),1,1);require("COMPLETE_ORIGINAL_DIA_NN_CAPTURED_WORKFLOW".equals(done.get("status"))&&Boolean.TRUE.equals(done.get("analysis_admitted")),"Missing overall DIA-NN result admission");
        require(pin(root.resolve("manifest.json"),1000000000L,check).equals(fingerprint(done.get("manifest"),1000000000L)),"Captured manifest bytes changed");
        var manifest=object(json(root.resolve("manifest.json"),1000000000));keys(manifest,"schema_version","profile","producer","tree","analysis_admitted","whole_paper_reproduced","neural_training_convergence_certified");integer(manifest.get("schema_version"),1,1);
        require("diann-library-free-captured-v1".equals(manifest.get("profile"))&&Boolean.TRUE.equals(manifest.get("analysis_admitted"))&&Boolean.FALSE.equals(manifest.get("whole_paper_reproduced"))&&Boolean.FALSE.equals(manifest.get("neural_training_convergence_certified")),"Expanded/changed capture claims");
        require(producer().equals(fingerprint(manifest.get("producer"),1000000000L)),"Use the exact producing JAR for saved DIA-NN readback");
        var s=DiannRequest.read(root.resolve("request.json"),false);require(NextflowJson.json(snapshot(root,s,check)).equals(NextflowJson.json(manifest.get("tree"))),"Complete saved file/directory namespace changed");
        var audit=audit(root,s,scratch,check);require(NextflowJson.json(audit).equals(NextflowJson.json(json(root.resolve("OUTPUT-AUDIT.json"),(int)Math.min(1000000000L,s.capacity().outputBytes())))),"Saved complete input/output consistency audit differs");
        require(Files.readString(root.resolve("WARNINGS.md")).equals(DiannWorkflow.warnings(s,audit)),"Saved warnings/actions changed");
        require(NextflowJson.json(snapshot(root,s,check)).equals(NextflowJson.json(manifest.get("tree"))),"Capture changed during full saved verification");
    }
    private static void process(Path root,String stage,List<String> command,String oldRoot,DiannRequest.Spec s)throws IOException {
        var record=object(json(root.resolve("processes/"+stage+"/process.json"),16777216));var p=s.process();var wrapped=new ArrayList<String>(List.of("/usr/bin/setsid","/usr/bin/prlimit","--as="+p.addressSpaceBytes(),"--cpu="+p.cpuSeconds(),"--fsize="+p.fileBytes(),"--nofile="+p.openFiles(),"--"));wrapped.addAll(command);
        require("completed-process-only".equals(record.get("status"))&&integer(record.get("exit_code"),0,0)==0&&list(record.get("owned_live_after_cleanup")).isEmpty()&&oldRoot.equals(record.get("working_directory"))&&wrapped.equals(strings(record.get("command")))&&NextflowJson.json(p).equals(NextflowJson.json(record.get("limits"))),"Original process/options/capacities are incomplete, changed or not terminal");
    }
    private static void require(boolean condition,String message)throws IOException{if(!condition)throw new IOException(message);}
}
